// RegisterDeviceToken is the resolver for the registerDeviceToken field.
func (r *mutationResolver) RegisterDeviceToken(ctx context.Context, deviceToken string, platform string) (bool, error) {
	userID := utils.GetUserID(ctx)
	uid, err := uuid.Parse(userID)
	if err != nil {
		return false, fmt.Errorf("invalid user ID")
	}

	if platform != "ios" && platform != "android" {
		return false, apperr.New(apperr.CodeUserError, "platform must be 'ios' or 'android'")
	}

	role := "user"
	if utils.GetIsAdmin(ctx) {
		role = "admin"
	}

	if err := r.NotificationService.RegisterDeviceToken(ctx, uid, deviceToken, platform, role); err != nil {
		return false, fmt.Errorf("failed to register device token: %w", err)
	}

	return true, nil
}

// UnregisterDeviceToken is the resolver for the unregisterDeviceToken field.
