func (r *queryResolver) OrderHistory(ctx context.Context, input *model.OrderHistoryInput) (*model.OrderHistoryResponse, error) {
	filter := orderDomain.OrderHistoryFilter{
		Page:  1,
		Limit: 20,
	}

	if input != nil {
		if input.First != nil && *input.First > 0 {
			filter.Limit = *input.First
		}
		if input.Page != nil && *input.Page > 0 {
			filter.Page = *input.Page
		}
		filter.StartDate = input.StartDate
		filter.EndDate = input.EndDate
		filter.Search = input.Search

		if input.Status != nil {
			s := orderDomain.OrderStatus(*input.Status)
			filter.Status = &s
		}
		if input.OrderType != nil {
			t := orderDomain.OrderType(*input.OrderType)
			filter.OrderType = &t
		}
	}

	orders, summary, err := r.OrderService.GetOrderHistory(ctx, filter)
	if err != nil {
		return nil, fmt.Errorf("failed to get order history: %w", err)
	}

	gqlOrders := Map(orders, func(order *orderDomain.Order) *model.Order {
		return ToGQLOrder(order)
	})

	return &model.OrderHistoryResponse{
		Orders: gqlOrders,
		Summary: &model.OrderHistorySummary{
			TotalOrders:  summary.TotalOrders,
			TotalRevenue: summary.TotalRevenue,
			AverageOrder: summary.AverageOrder,
		},
	}, nil
}

// MyOrders is the resolver for the myOrders field.
func (r *queryResolver) MyOrders(ctx context.Context, first *int, page *int) ([]*model.Order, error) {
	const (
		defaultFirst = 5
		defaultPage  = 1
	)
	f := defaultFirst
	if first != nil && *first > 0 {
		f = *first
	}
	p := defaultPage
	if page != nil && *page > 0 {
		p = *page
	}

	userID := utils.GetUserID(ctx)

	// Cast userID to uuid.UUID
	userUUID, err := uuid.Parse(userID)
	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}

	o, err := r.OrderService.GetPaginatedOrders(ctx, p, f, &userUUID)
	if err != nil {
		return nil, fmt.Errorf("failed to get orders: %w", err)
	}

	orders := Map(o, func(order *orderDomain.Order) *model.Order {
		return ToGQLOrder(order)
	})

	return orders, nil
}

// MyOrder is the resolver for the myOrder field.
func (r *queryResolver) MyOrder(ctx context.Context, id uuid.UUID) (*model.Order, error) {
	userID := utils.GetUserID(ctx)

	// @TODO: Check if the user is the owner of the order in the service layer.
	o, _, err := r.OrderService.GetOrderByID(ctx, id)
	if err != nil {
		return nil, orderLookupError(err)
	}

	if o == nil {
		return nil, nil
	}

	// @TODO: Remove when the service layer check is implemented.
	if o.UserID.String() != userID {
		return nil, &gqlerror.Error{
			Message:    "FORBIDDEN: order does not belong to caller",
			Path:       graphql.GetPath(ctx),
			Extensions: map[string]any{"code": "FORBIDDEN"},
		}
	}

	// Map the order to the GraphQL model
	order := ToGQLOrder(o)

	return order, nil
}

// MyOrderedProducts is the resolver for the myOrderedProducts field.
