// MyOrderUpdated is the resolver for the myOrderUpdated field.
func (r *subscriptionResolver) MyOrderUpdated(ctx context.Context, orderID uuid.UUID) (<-chan *model.Order, error) {
	// The @auth directive guarantees a non-empty userID.
	userID := utils.GetUserID(ctx)

	// Verify the order belongs to this user
	order, _, err := r.OrderService.GetOrderByID(ctx, orderID)
	if err != nil {
		return nil, &gqlerror.Error{
			Message:    "NOT_FOUND: order not found",
			Path:       graphql.GetPath(ctx),
			Extensions: map[string]any{"code": "NOT_FOUND"},
		}
	}
	if order.UserID.String() != userID {
		return nil, &gqlerror.Error{
			Message:    "FORBIDDEN: order does not belong to caller",
			Path:       graphql.GetPath(ctx),
			Extensions: map[string]any{"code": "FORBIDDEN"},
		}
	}

	topic := fmt.Sprintf("orderUpdated:%s", orderID)
	ch := make(chan *model.Order, 1)
	sub := r.Broker.Subscribe(topic)

	go func() {
		defer close(ch)
		defer r.Broker.Unsubscribe(topic, sub)
		for {
			select {
			case <-ctx.Done():
				return
			case msg, ok := <-sub:
				if !ok {
					return
				}
				if o, ok := msg.(*model.Order); ok {
					select {
					case ch <- o:
					case <-ctx.Done():
						return
					}
				}
			}
		}
	}()

	return ch, nil
}

